const items = $("Get many messages").all();

for (const item of items) {
  const email = item.json;

  // Clean invisible Unicode characters and extra spaces
  const clean = (value) =>
    String(value || "")
      .replace(/[\u200B-\u200F\u2060\uFEFF\u00AD\u034F\u2061-\u2064]/g, "")
      .replace(/\s+/g, " ")
      .trim();

  // Gmail fields from Get many messages
  const subject = clean(email.subject || email.Subject);
  const snippet = clean(email.snippet || email.Snippet);
  const from = clean(email.from || email.From);

  const text = `${subject} ${snippet}`.toLowerCase();
  const sender = from.toLowerCase();

  email.cleanSubject = subject;
  email.cleanSnippet = snippet;

  // 1. Ignore OTPs and verification codes
  const isOTP =
    /\b(otp|one[- ]time password|verification code|security code|login code|password reset code)\b/i.test(text) ||
    /\b(your code is|use this code|code to verify|verify your email)\b/i.test(text);

  // 2. Identify job alerts that should be reviewed manually
  const isJobAlert =
    /\b(job alert|jobs matching|job recommendations|hiring digest|jobs newsletter)\b/i.test(text) ||
    /noreply@glassdoor\.com/i.test(sender);

  // 3. Identify direct job opportunities
  const isJob =
    /\b(job opportunity|we are hiring|job opening|job offer|interview invitation|shortlisted|recruiter|application status|mobile app developer|apply for this role|submit (a |your )?application|career opportunity|vacancy|vacancies)\b/i.test(text);

  // 4. Identify order, delivery, booking and customer support emails
  const isOrderOrSupport =
    /\b(order confirmation|order update|order status|order delivered|order shipped|payment received|payment confirmation|payment failed|refund|return request|delivery update|tracking number|booking confirmation|reservation confirmation|support ticket|customer support|issue resolved|your order)\b/i.test(text);

  // 5. Identify personal messages that may need a response
  const isPersonal =
    /\b(please reply|please respond|get back to me|let me know|could you confirm|can you confirm|please confirm|what do you think|are you available|following up on my email|hope you are doing well)\b/i.test(text);

  // 6. Identify promotions, advertising and newsletters
  const isPromotion =
    /\b(unsubscribe|newsletter|promotional offer|special offer|limited time offer|discount code|shop now|sale ends|weekly digest|sponsored|cash prizes|exclusive deals|save \d+%|don't miss out)\b/i.test(text) ||
    /\b(promotions?|advertisement|marketing email|event promotion)\b/i.test(text) ||
    /noreply@unstop\.news/i.test(sender) ||
    /newsletters-noreply@linkedin\.com/i.test(sender) ||
    /\b(apply for voyagehack|land .* cash prizes)\b/i.test(text);

  // 7. Classification priority
  if (!subject && !snippet) {
    email.classification = "REVIEW";
  } else if (isOTP || isPromotion) {
    email.classification = "IGNORE";
  } else if (isJobAlert) {
    email.classification = "REVIEW";
  } else if (isJob || isOrderOrSupport || isPersonal) {
    email.classification = "REPLY_NEEDED";
  } else {
    email.classification = "REVIEW";
  }

  // 8. Prepare the IF node boolean condition
  email.classification = String(email.classification).trim();
  email.shouldDraft = email.classification === "REPLY_NEEDED";
}

console.log(
  items.map(item => ({
    subject: item.json.cleanSubject,
    classification: item.json.classification,
    shouldDraft: item.json.shouldDraft
  }))
);

return items;

const reply = $json.text || "";

const subject = $("Get many messages").item.json.Subject || "";
const from = $("Get many messages").item.json.From || "";

const toMatch = from.match(/<([^>]+)>/);
const to = toMatch ? toMatch[1] : from;

const mime = [
  `To: ${to}`,
  `Subject: Re: ${subject}`,
  "MIME-Version: 1.0",
  "Content-Type: text/plain; charset=UTF-8",
  "Content-Transfer-Encoding: 8bit",
  "",
  reply
].join("\r\n");

const raw = Buffer.from(mime, "utf8")
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");

return {
  json: {
    originalEmailId: $("Get many messages").item.json.id,
    message: { raw }
  }
};
